Final output schema: {"$defs": {"PriceReference": {"additionalProperties": false, "properties": {"reference": {"title": "Reference", "type": "string"}, "price_field": {"enum": ["open", "high", "low", "close"], "title": "Price Field", "type": "string"}, "price": {"title": "Price", "type": "string"}, "source": {"$ref": "#/$defs/TriggerSource"}}, "required": ["reference", "price_field", "price", "source"], "title": "PriceReference", "type": "object"}, "Setup": {"additionalProperties": false, "properties": {"type": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Type"}, "trigger_status": {"anyOf": [{"enum": ["pending", "triggered", "present", "absent", "failed", "stale", "unknown"], "type": "string"}, {"type": "null"}], "default": null, "title": "Trigger Status"}, "signal_quality": {"anyOf": [{"enum": ["clear", "weak", "failed", "absent", "unknown"], "type": "string"}, {"type": "null"}], "default": null, "title": "Signal Quality"}, "location_assessment": {"anyOf": [{"enum": ["favorable", "neutral", "poor", "unknown"], "type": "string"}, {"type": "null"}], "default": null, "title": "Location Assessment"}, "no_trade_reason": {"anyOf": [{"enum": ["no_trigger", "poor_location", "weak_signal", "failed_breakout", "opposing_pressure", "insufficient_data", "timeframe_conflict", "stale_or_late", "missing_invalidation", "balanced_context"], "type": "string"}, {"type": "null"}], "default": null, "title": "No Trade Reason"}}, "title": "Setup", "type": "object"}, "Trigger": {"additionalProperties": false, "properties": {"reference": {"title": "Reference", "type": "string"}, "price_field": {"enum": ["open", "high", "low", "close"], "title": "Price Field", "type": "string"}, "price": {"title": "Price", "type": "string"}, "source": {"$ref": "#/$defs/TriggerSource"}, "kind": {"enum": ["market", "stop", "limit"], "title": "Kind", "type": "string"}, "direction": {"enum": ["at", "above", "below"], "title": "Direction", "type": "string"}}, "required": ["reference", "price_field", "price", "source", "kind", "direction"], "title": "Trigger", "type": "object"}, "TriggerSource": {"additionalProperties": false, "properties": {"timeframe": {"title": "Timeframe", "type": "string"}, "bar_index": {"minimum": 0, "title": "Bar Index", "type": "integer"}, "open_time_ms": {"minimum": 0, "title": "Open Time Ms", "type": "integer"}, "close_time_ms": {"minimum": 0, "title": "Close Time Ms", "type": "integer"}}, "required": ["timeframe", "bar_index", "open_time_ms", "close_time_ms"], "title": "TriggerSource", "type": "object"}}, "additionalProperties": false, "properties": {"schema": {"const": "brooks.trade-intent.v2", "title": "Schema", "type": "string"}, "role": {"const": "TRADER", "title": "Role", "type": "string"}, "decision": {"enum": ["ENTER_LONG", "ENTER_SHORT", "NO_TRADE"], "title": "Decision", "type": "string"}, "symbol": {"title": "Symbol", "type": "string"}, "decision_time_ms": {"minimum": 0, "title": "Decision Time Ms", "type": "integer"}, "market_context": {"anyOf": [{"additionalProperties": true, "type": "object"}, {"type": "null"}], "title": "Market Context"}, "setup": {"anyOf": [{"$ref": "#/$defs/Setup"}, {"type": "null"}]}, "decision_timeframe": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Decision Timeframe"}, "context_timeframes_used": {"items": {"type": "string"}, "title": "Context Timeframes Used", "type": "array"}, "entry_mechanism": {"enum": ["continuation", "breakout", "breakout_pullback", "reversal", "none", "unclear"], "title": "Entry Mechanism", "type": "string"}, "trigger": {"anyOf": [{"$ref": "#/$defs/Trigger"}, {"type": "null"}]}, "invalidation": {"anyOf": [{"$ref": "#/$defs/PriceReference"}, {"type": "null"}]}, "evidence_for": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence For", "type": "array"}, "evidence_against": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence Against", "type": "array"}, "qualitative_confidence": {"enum": ["high", "medium", "low"], "title": "Qualitative Confidence", "type": "string"}, "uncertainty": {"items": {"type": "string"}, "minItems": 1, "title": "Uncertainty", "type": "array"}, "conditions_that_change_market_read": {"items": {"type": "string"}, "minItems": 1, "title": "Conditions That Change Market Read", "type": "array"}}, "required": ["schema", "role", "decision", "symbol", "decision_time_ms", "market_context", "setup", "decision_timeframe", "context_timeframes_used", "entry_mechanism", "trigger", "invalidation", "evidence_for", "evidence_against", "qualitative_confidence", "uncertainty", "conditions_that_change_market_read"], "title": "TradeIntentV2", "type": "object"}
Input: {"decision_time_ms": 1789973999999, "macro_contexts": {"D1": {"context": {"always_in": "long", "always_in_relevance": "low", "breakout_mode": true, "confidence": "medium", "decision_time_ms": 1789948799999, "directional_pressure": "bull", "evidence_against": ["30 of the last 33 bars are a two-sided 2357.18-2700 range with heavy overlap; the 2771 spike high made 30 bars ago is still the window high, so trend continuation is not confirmed.", "Bar 89 closed below the midpoint of its 445.69 range (buy climax), and the 2609.02-2700 area has now rejected upside probes three times (bar 113 close 2514.07 area, bar 110 high 2680 closed 2514.72, bar 118 high 2700 closed 2632.98 in the lower third of its range).", "The 120-bar window contains a full 36% bear leg (2116.86 to 1368.42) in its first 14 bars, so the window is not a single clean bull trend and the bear-trend context is only 100 bars old.", "No bar closes above 2700 yet: bar 118 leaves an upper tail and bar 119 is an inside bar, so the current push is still a boundary test, and repeated boundary tests in a range often resolve either way."], "evidence_for": ["Swing progression since the 1368.42 low is higher lows (1512.91 bar 33, 1512.91 -> 2357.18/2358.62 bars 101/114) and higher highs (1845.09, 1954.36, 1974.46, 2771), which is a bull sequence at the window level.", "The bar 87-89 spike closed far above the 24-bar 1821.49-1974.46 range and the following 30 bars never traded back below 2293.80 (bar 87 high), so the breakout was accepted rather than reversed: the range/base is left behind.", "The window's three highest closes are the last three bars (2612.02, 2632.98, 2642.90), and bar 119 closes near the top of its range at 2642.90, showing buyers still pressing at the range top at the decision time.", "Lows inside the post-spike range rise after bar 101 (2374.01, 2411.04, 2413.82, 2436.87, 2568.16), a mild upward tilt consistent with a bull flag rather than a topping structure."], "missing_information": [], "observations": ["Bars 0-13 are a bear leg: window opens 2116.86, high 2139.34 (bar 1), low 1368.42 (bar 13), about -36% from the high.", "Bar 13 (open 1581.32, high 1599.27, low 1368.42, close 1568.55) closes 200.13 above its low, near the top of its 230.85 range: the leg ends in a climactic reversal bar rather than a trend-continuation close.", "After 1368.42 the market rallies to 1845.09 (bar 22 high) and then pulls back to 1512.91 (bar 33 low), a higher low; the subsequent leg reaches 1954.36 (bar 59 high) and 1974.46 (bar 64 high).", "Bars 63-86 are a 24-bar range between 1974.46 (bar 64 high) and 1821.49 (bar 71 low); bar 63 prints 1959.37, just above bar 59's 1954.36, and bar 64 immediately reverses to close 1891.41 near its low (failed breakout/upthrust).", "Bar 87 opens 1916.51 inside that range and closes 2252.16 (high 2293.80, low 1905.63), a +17.5% close-to-close bull bar; bar 88 closes 2326.32 and bar 89 reaches 2771.", "Bar 89 (open 2326.31, high 2771, low 2325.31, close 2515.30) closes below the midpoint 2548.16 of its 445.69 range: a long upper tail, and the 2771 high has not been exceeded in the following 30 bars.", "Bars 90-119 trade between 2357.18 (bar 101 low) and 2700 (bar 118 high) with heavy overlap and never return below 2293.80 (bar 87 high): the breakout zone 1821.49-1974.46 is left behind.", "Upside probes at 2680 (bar 110 high, close 2514.72) and 2700 (bar 118 high, close 2632.98, i.e. the lower third of its 2604.75-2700 range) both closed back inside the 30-bar range.", "Bar 114 sells to 2358.62 and closes 2397.10; the next five closes rise: 2416.57, 2446.22, 2612.02, 2632.98, 2642.90. Those last three are the three highest closes of the whole 120-bar window (next highest is 2515.30 on bar 89).", "Bar 119 (open 2632.98, high 2645.88, low 2568.16, close 2642.90) is an inside bar versus bar 118 and closes 57.10 below the 2700 high, near the top of its own range."], "phase": "range", "primary_regime": "bull-trend", "role": "CONTEXT_ANALYST", "schema": "brooks.market-context.v2", "structures": [{"description": "Opening bear leg of the window ending in a climactic bar: 2116.86 open, high 2139.34 (bar 1), low 1368.42 (bar 13). Bar 13 is a bear bar closing 200.13 above its low in the upper part of its range, the exhaustion bar of the leg.", "end_time_ms": 1780790399999, "kind": "climax", "lower_boundary": "1368.42", "start_time_ms": 1779580800000, "upper_boundary": "2139.34"}, {"description": "Mid-window trading range, 24 bars (63-86) confined between 1974.46 (bar 64 high) and 1821.49 (bar 71 low), width 152.97 (about 8%). Bar 63 marginally exceeds the prior swing high 1954.36 and bar 64 reverses to close 1891.41 near its low: a failed breakout above the prior high.", "end_time_ms": 1787097599999, "kind": "range", "lower_boundary": "1821.49", "start_time_ms": 1785024000000, "upper_boundary": "1974.46"}, {"description": "Bull spike out of the 24-bar range: bar 87 opens 1916.51 inside the range and closes 2252.16 (high 2293.80, low 1905.63); bars 88 (close 2326.32) and 89 (open 2326.31, high 2771, close 2515.30) extend it. Bar 89 closes below the midpoint of its 445.69 range (long upper tail), so the third bar is climactic.", "end_time_ms": 1787356799999, "kind": "breakout", "lower_boundary": "1905.63", "start_time_ms": 1787097600000, "upper_boundary": "2771"}, {"description": "Post-spike trading range, 30 bars (90-119): overlapping two-sided trade between 2357.18 (bar 101 low) and 2700 (bar 118 high), never returning below 2293.80 (bar 87 high). Spike highs at 2680 (bar 110) and 2700 (bar 118) were both sold back into the range; lows after bar 101 rise from 2374.01 (bar 102) to 2568.16 (bar 119) with one near-retest at 2358.62 (bar 114).", "end_time_ms": 1789948799999, "kind": "range", "lower_boundary": "2357.18", "start_time_ms": 1787356800000, "upper_boundary": "2700"}, {"description": "Recent bull leg off bar 114's low 2358.62: five rising closes 2416.57, 2446.22, 2612.02, 2632.98, 2642.90, the highest closes of the window. Bar 117 closes 2612.02 near its 2643.52 high; bar 119 is an inside bar versus bar 118 and closes 2642.90, 57.10 under the 2700 range top. Still a leg inside the 30-bar range, not an accepted breakout.", "end_time_ms": 1789948799999, "kind": "swing", "lower_boundary": "2358.62", "start_time_ms": 1789430400000, "upper_boundary": "2700"}], "symbol": "ETH-USDT", "timeframe": "D1", "transition_conditions": ["A daily close above 2700 (bar 118 high) with a further bull close would mark acceptance of an upside breakout from the 30-bar range and support continued bull-trend/channel behaviour.", "A bear close below 2568.16 (bar 119 low) followed by a break of 2357.18 (bar 101 low) would break the 30-bar range low and shift the read toward a lower high under 2771 and a range-down resolution.", "Continuation of overlapping bars contained inside 2436.87 (bar 117 low) and 2700 keeps the phase 'range' and keeps always-in relevance low.", "A move back below 2293.80 (bar 87 high, the top of the breakout bar's range) would undercut breakout acceptance and move the classification toward transition-unclear."], "window_bars": 120}, "freshness": "current"}, "H4": {"context": {"always_in": "long", "always_in_relevance": "medium", "breakout_mode": false, "confidence": "medium", "decision_time_ms": 1789963199999, "directional_pressure": "bull", "evidence_against": ["The whole 120-bar window can be read as one large two-sided range 2357.18-2700; the current leg is arriving at that range high, so the 'trend' may be the upper half of a range rather than a sustained directional market.", "Equal highs at 2700 (bars 109 and 119) form a double top at a round number: bar 109's print was rejected in the same bar and led to a pullback to 2568.16, showing supply at that level.", "The last bar closed below its own midpoint (2670.85) with a 35.27 upper tail, and bar 117 closed 13.95 below its high - the push into 2700 is being sold into.", "Upside probes in this window have repeatedly failed: bar 62's 2680 spike was fully retraced and bar 82's 2609.02 probe reversed in a single bar into a 250.4-point decline."], "evidence_for": ["Since the 2358.62 low (bar 87) the window shows four successively higher swing lows (2358.62, 2370.54, 2436.87, 2568.16) and four higher swing highs (2482.09, 2519.81, 2643.52, 2700), the standard higher-high/higher-low bull sequence.", "Bull trend bars carry the move: bar 104 (2507.15 to 2585.5, close 2578.6) and bar 105 (close 2636.28), then bars 116-119 with rising closes and bar 116 closing exactly at its high 2611.", "The seven-bar tight range 2604.75-2658.79 (bars 106-112) sat above the earlier range top and behaved as a bull flag: after the bars 113-115 dip, price returned to the 2700 high while the 2568.16 pullback low stayed above the prior 2519.81 swing high.", "The bars 86-87 bear breakout failed: 2358.62 held above the earlier 2357.18 low, and the recovery went on to exceed the prior range top 2609.02 (bar 82) at bar 104, so the breakout above the older range came with follow-through until 2700."], "missing_information": [], "observations": ["Last closed bar (open_time 1789948800000) prints open 2642.9, high 2700, low 2641.7, close 2664.73: a bull bar that closed 35.27 below its high and 6.12 below its own midpoint 2670.85, i.e. a bull close with a visible upper tail at 2700.", "Two exactly equal highs at 2700 (bar 109, open_time 1789804800000, and bar 119, open_time 1789948800000), 10 bars apart, above every other print in the 120-bar window; bar 109 was rejected the same bar (close 2638.49, 61.51 below the high).", "Bars 116-119 are four consecutive bull bars with rising closes 2611, 2631.93, 2642.9, 2664.73; bar 116 closed exactly at its high 2611 and bar 118 closed 1.96 below its high.", "Bars 106-112 form a seven-bar tight range 2604.75-2658.79 (range 54.04) above the prior range top; the 2700 print at bar 109 was an outlier spike inside it, and bars 113-115 then traded below the range low to 2568.16 before bars 116-119 rallied back to 2700.", "The move from the 2358.62 low (bar 87) to the 2700 high (bar 119) is 341.38 points (+14.5%) over 33 bars, with pullbacks of 82.94 (2519.81 to 2436.87) and 74.37 (2643.52 to 2568.16).", "The long two-sided range at bars 20-61 has repeated highs 2527.29/2528.8 and lows 2441.33/2436.73; its 2411.04 floor (bar 56) was breached only by the bars 86-87 bear spike, and no close after bar 87 is below 2392.87 (bar 92).", "Precedent of failed upside probes exists in the window: bar 62's 235.81-point spike (2444.19-2680) was fully given back, every close from bar 63 to bar 85 staying at or below 2609.02, and the bars 82-87 decline covered 250.4 points (2609.02 to 2358.62).", "No multi-bar tight sideways consolidation precedes the current bar; the last four bars are directional bull bars testing 2700, so the market is at a resistance test rather than in a breakout-mode squeeze."], "phase": "channel", "primary_regime": "bull-trend", "role": "CONTEXT_ANALYST", "schema": "brooks.market-context.v2", "structures": [{"description": "Opening bear leg: bars 0-7 (open_time 1788235200000 to 1788350399999) mark down from 2483.9 to 2357.18, then six overlapping bars (indices 8-13) hold roughly 2373-2417.19, a base. The 2357.18 low is later retested from above by 2358.62 (bar 87).", "end_time_ms": 1788436799999, "kind": "swing", "lower_boundary": "2357.18", "start_time_ms": 1788235200000, "upper_boundary": "2483.9"}, {"description": "Bull spike, bars 14-19: large bull bars from 2404.35 to the 2537.57 high, closes 2506.79-2523.22. The 2537.57 high was not exceeded for the next 43 bars.", "end_time_ms": 1788523199999, "kind": "breakout", "lower_boundary": "2404.35", "start_time_ms": 1788436800000, "upper_boundary": "2537.57"}, {"description": "Two-sided trading range, bars 20-61 (open_time 1788523200000 to 1789127999999): repeated highs 2527.29/2528.8 against lows 2441.33/2436.73, heavy bar overlap, then a lower probe to 2411.04 (bar 56) with recovery close 2457.12 (bar 61). Approximate area 2436-2530 with a down-probe to 2411.04.", "end_time_ms": 1789127999999, "kind": "range", "lower_boundary": "2411.04", "start_time_ms": 1788523200000, "upper_boundary": "2528.8"}, {"description": "Single bull spike bar (index 62): range 2444.19-2680, largest range in the window (235.81), close 2555.52, i.e. 124.48 below the high. It exceeded the 2528.8 range top but closed back inside the older range, and price never closed above 2609.02 during the following 23 bars.", "end_time_ms": 1789142399999, "kind": "breakout", "lower_boundary": "2444.19", "start_time_ms": 1789128000000, "upper_boundary": "2680"}, {"description": "Trading range, bars 63-85: prices hold 2464.27-2544.63 for about 18 bars, then a bull probe to 2609.02 (bar 82) closing 94.95 below that high at 2514.07, followed by a slide to 2464.27 (bar 85).", "end_time_ms": 1789473599999, "kind": "range", "lower_boundary": "2464.27", "start_time_ms": 1789142400000, "upper_boundary": "2609.02"}, {"description": "Failed bear breakout: bars 86-87 drive to 2358.62, breaking the bars 20-61 range floor 2411.04 but holding 1.44 above the earlier window low 2357.18, then reversing up; after this low no close is below 2392.87. This reads as a failed breakout / double bottom with the bar 7 low rather than a sustained bear leg.", "end_time_ms": 1789502399999, "kind": "other", "lower_boundary": "2358.62", "start_time_ms": 1789473600000, "upper_boundary": "2484.35"}, {"description": "Bull trend leg since the 2358.62 low (bar 87): higher swing lows 2358.62, 2370.54, 2436.87, 2568.16 and higher swing highs 2482.09, 2519.81, 2643.52, 2700. Two bull spikes (indexes 104-105 and 116-119) with shallow 3% pullbacks; the 2700 high is repeated 10 bars apart (bars 109 and 119), an equal-high test at the top of this leg.", "end_time_ms": 1789963199999, "kind": "channel", "lower_boundary": "2358.62", "start_time_ms": 1789488000000, "upper_boundary": "2700"}], "symbol": "ETH-USDT", "timeframe":